let trans = "";
let interpret = "";
let mood = "";

// Loop through all inputs
for (const item of $input.all()) {
  const output = item.json.output || "";
  const lines = output.split("\n");

  let foundInterpret = false;
  let foundMood = false;

  for (let line of lines) {
    line = line.trim();
    if (!line) continue;

    // Check for Interpretation header
    if (line.startsWith("**Interpretation:**")) {
      foundInterpret = true;
      foundMood = false;
      continue;
    }

    // Check for MoodAnalyze header
    if (line.startsWith("MoodAnalyze:")) {
      foundMood = true;
      foundInterpret = false;
      continue;
    }

    // Separate content by context
    if (foundMood) {
      // mood line: must have number + %
      if (/^\d+\s+\d+%$/.test(line)) {
        mood += line + "\n";
      }
    } else if (foundInterpret) {
      interpret += line + "\n";
    } else {
      trans += line + "\n";
    }
  }
}

// Return parsed object
return {
  translation: trans.trim(),
  interpretation: interpret.trim(),
  moodAnalyze: mood.trim() || null
};
